namespace ghidra.app.plugin.core.decompile.actions;



using org.apache.commons.lang3;

using docking;
using docking.action;
using docking.widgets;
using ghidra.app.decompiler.component;
using ghidra.app.decompiler.component;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.util;

public class FindAction : AbstractDecompilerAction {
	private DecompilerFindDialog findDialog;

	public FindAction() : base("Find")
    {
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionFind"));
		setPopupMenuData(new MenuData(new string[] { "Find..." }, "Decompile"));
		setKeyBindingData(
			new KeyBindingData(KeyEvent.VK_F, DockingUtils.CONTROL_KEY_MODIFIER_MASK));
		setEnabled(true);
	}

	/* @Override */
	public KeyBindingType getKeyBindingType() {
		return KeyBindingType.SHARED;
	}

	/* @Override */
	public void dispose() {
		if (findDialog != null) {
			findDialog.dispose();
		}
		base.dispose();
	}

	protected FindDialog getFindDialog(DecompilerPanel decompilerPanel) {
		if (findDialog == null) {
			findDialog = new DecompilerFindDialog(decompilerPanel);
		}
		return findDialog;
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		return true;
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		DecompilerPanel decompilerPanel = context.getDecompilerPanel();
		FindDialog dialog = getFindDialog(decompilerPanel);
		string text = decompilerPanel.getSelectedText();
		if (text == null) {
			text = decompilerPanel.getHighlightedText();

			// note: if we decide to grab the text under the cursor, then use
			// text = decompilerPanel.getTextUnderCursor();
		}

		if (!StringUtils.isBlank(text)) {
			dialog.setSearchText(text);
		}

		if (dialog.isShowing()) {
			dialog.toFront();
			return;
		}

		// show over the root frame, so the user can still see the Decompiler window
		context.getTool().showDialog(dialog);
	}
}
